def _nominal_time_facet(dag_run: DagRun) -> dict[str, nominal_time_run.NominalTimeRunFacet]:
    """Build the ``nominalTime`` run facet from a DAG run's data interval."""
    data_interval_start = dag_run.data_interval_start
    if data_interval_start is None:
        return {}
    if isinstance(data_interval_start, datetime.datetime):
        data_interval_start = data_interval_start.isoformat()
    data_interval_end = dag_run.data_interval_end
    if isinstance(data_interval_end, datetime.datetime):
        data_interval_end = data_interval_end.isoformat()
    return {
        "nominalTime": nominal_time_run.NominalTimeRunFacet(
            nominalStartTime=data_interval_start,
            nominalEndTime=data_interval_end,
            producer=_PRODUCER,
        )
    }


def build_task_event_run_facets(
    *,
    task_instance,
    dag_run,
    dag,
    task,
    task_uuid: str,
    ti_state,
    parent_run_id: str,
    parent_job_name: str | None = None,
    dr_conf: dict | None = None,
    additional_run_facets: dict | None = None,
) -> dict[str, Any]:
    """
    Compose all run facets for a task-level OpenLineage event.

    Merges (in priority order, internal facets winning over user-provided
    ``additional_run_facets``): user-provided custom facets, parent, airflow,
    debug, processing_engine and nominalTime sections.
    """
    internal_run_facets: dict[str, Any] = {
        **get_user_provided_run_facets(task_instance, ti_state),
        **get_task_parent_run_facet(
            parent_run_id=parent_run_id,
            parent_job_name=parent_job_name if parent_job_name is not None else dag.dag_id,
            dr_conf=dr_conf if dr_conf is not None else dag_run.conf,
        ),
        **get_airflow_run_facet(dag_run, dag, task_instance, task, task_uuid),
        **get_airflow_debug_facet(),
        **get_processing_engine_facet(),
        **_nominal_time_facet(dag_run),
    }
    # Internal facets take priority over user-supplied additional facets.
    return {**(additional_run_facets or {}), **internal_run_facets}


def build_task_event_job_facets(
    *,
    task,
    dag,
    additional_job_facets: dict | None = None,
) -> dict[str, Any]:
    """
    Compose all job facets for a task-level OpenLineage event.

    Always includes a ``jobType`` facet. Adds ``documentation`` (task doc
    preferred over dag doc), ``ownership`` (task owner, falling back to dag
    owner when the task uses the default Airflow owner) and ``tags`` facets.
    Internal facets take priority over user-supplied ``additional_job_facets``.
    """
    internal_job_facets: dict[str, Any] = {
        "jobType": job_type_job.JobTypeJobFacet(
            jobType="TASK",
            integration="AIRFLOW",
            processingType="BATCH",
            producer=_PRODUCER,
        )
    }

    doc, doc_type = get_task_documentation(task)
    if not doc:
        doc, doc_type = get_dag_documentation(dag)
    if doc:
        internal_job_facets["documentation"] = documentation_job.DocumentationJobFacet(
            description=doc,
            contentType=doc_type,
            producer=_PRODUCER,
        )

    # If task owner is the default ("airflow"), use DAG owner instead as it may have more details.
    owner = task.owner
    if owner == _DEFAULT_AIRFLOW_OWNER:
        owner = dag.owner
    if owner:
        owners = [o.strip() for o in owner.split(",") if o.strip()]
        if owners:
            internal_job_facets["ownership"] = ownership_job.OwnershipJobFacet(
                owners=[ownership_job.Owner(name=o) for o in sorted(owners)],
                producer=_PRODUCER,
            )

    if dag.tags:
        internal_job_facets["tags"] = tags_job.TagsJobFacet(
            tags=[
                tags_job.TagsJobFacetFields(key=tag, value=tag, source="AIRFLOW")
                for tag in sorted(dag.tags)
            ],
            producer=_PRODUCER,
        )

    # Internal facets take priority over user-supplied additional facets.
    return {**(additional_job_facets or {}), **internal_job_facets}


def next_query_counter_from_context() -> str:
    """
    Return the next sequential manual-query counter as a string.

    The counter is stored under ``_openlineage_manual_query_counter`` in the
    current Airflow execution context, so it is isolated per context instance
    and restarts at ``1`` for each new task execution. When no active context
    is available a random 8-character string is returned instead.
    """
    try:
        context = get_current_context()
    except Exception:
        import random
        import string

        log.info(
            "OpenLineage encountered an error when retrieving query counter from context, "
            "a random value will be used instead.",
            exc_info=True,
        )
        return "".join(random.choices(string.ascii_lowercase + string.digits, k=8))

    counter = context.get("_openlineage_manual_query_counter", 0) + 1
    context["_openlineage_manual_query_counter"] = counter
    return str(counter)


